insert into topic_contents (topic_id, summary, content_md, example_question) values ('ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'Ünlü ve ünsüz uyumu, ünsüz yumuşaması/sertleşmesi, ünlü düşmesi ve kaynaştırma ünsüzleri gibi ses olaylarını kapsayan bu konu, Türkçenin ses bilgisi kurallarını örneklerle açıklar.', '## Büyük Ünlü Uyumu (Kalınlık-İncelik Uyumu)
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('82c89bf9-b824-4eda-b869-c2179bf5e02f', 'ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'kolay'::difficulty_level, 'Aşağıdaki kelimelerden hangisi büyük ünlü uyumuna (kalınlık-incelik uyumuna) aykırıdır?', 'Büyük ünlü uyumu kuralını kelimeler üzerinde uygular.', '''Kalem'' kökü Arapça kökenli olup ilk hecesinde kalın ünlü (a), ikinci hecesinde ince ünlü (e) bulunur; bu nedenle kelime büyük ünlü uyumuna aykırıdır. Diğer seçeneklerdeki kelimelerin tüm heceleri ya kalın ya da ince ünlülerden oluşur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('82c89bf9-b824-4eda-b869-c2179bf5e02f', 'kalemlik', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('82c89bf9-b824-4eda-b869-c2179bf5e02f', 'yapraklar', false, 1);
