insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('dcb84efc-8ed4-4ec8-8251-bb7979cfb0ad', 'ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'kolay'::difficulty_level, 'Aşağıdaki kelimelerin hangisinde ünsüz yumuşaması (p, ç, t, k seslerinin yumuşaması) görülür?', 'Ünsüz yumuşaması kuralını örneklerde tespit eder.', '''Ağaç'' kökündeki sert ünsüz ''ç'', ünlüyle başlayan iyelik eki ''-ı'' aldığında yumuşayarak ''c''ye dönüşmüş ve ''ağacı'' biçimini almıştır. Diğer seçeneklerde ünsüzle başlayan ekler geldiği için yumuşama gerçekleşmez.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dcb84efc-8ed4-4ec8-8251-bb7979cfb0ad', 'kitaptan', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dcb84efc-8ed4-4ec8-8251-bb7979cfb0ad', 'ağacı', true, 1);
