insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('183f9726-9198-460f-8319-f4a5bb5f1fe5', 'ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ünlü düşmesi (hece düşmesi) örneği vardır?', 'Ünlü düşmesi kuralının işlediği kelimeleri cümlede belirler.', '''Burun'' kelimesi ünlüyle başlayan iyelik eki ''-u'' aldığında ikinci hecesindeki dar ünlü ''u'' düşerek ''burnu'' biçimini almıştır. Diğer cümlelerdeki kelimelerde böyle bir ses düşmesi yoktur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('183f9726-9198-460f-8319-f4a5bb5f1fe5', 'Burnu kanayan çocuğu hemen hastaneye götürdüler.', true, 0);
