insert into question_choices (question_id, choice_text, is_correct, order_index) values ('183f9726-9198-460f-8319-f4a5bb5f1fe5', 'Kitapları düzenli bir şekilde masaya bıraktı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('183f9726-9198-460f-8319-f4a5bb5f1fe5', 'Sınavdan beklediğinden yüksek bir not aldı.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('3ba99267-70c5-469b-ae8f-3ecb3d52cb99', 'ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'orta'::difficulty_level, 'Aşağıdaki kelimelerin hangisinde kaynaştırma ünsüzü kullanılmıştır?', 'Kaynaştırma ünsüzlerinin kullanıldığı kelimeleri ayırt eder.', 'Ünlüyle biten ''kapı'' kelimesi ünlüyle başlayan ''-ı'' ekini aldığında iki ünlünün yan yana gelmesini önlemek için araya ''y'' kaynaştırma ünsüzü girmiş ve ''kapıyı'' biçimi oluşmuştur. Diğer seçeneklerdeki ekler ünsüzle başladığı için kaynaştırma ünsüzüne gerek yoktur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ba99267-70c5-469b-ae8f-3ecb3d52cb99', 'kapıyı', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ba99267-70c5-469b-ae8f-3ecb3d52cb99', 'evden', false, 1);
