insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3ba99267-70c5-469b-ae8f-3ecb3d52cb99', 'sokakta', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('d46bd22e-5c11-486b-9f0c-5768bd9d69d4', 'ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'zor'::difficulty_level, 'Aşağıdaki kelimelerden hangisi küçük ünlü uyumuna (düzlük-yuvarlaklık uyumuna) aykırıdır?', 'Küçük ünlü uyumu kuralını ileri düzeyde uygular.', 'Yuvarlak bir ünlüden (o) sonra ancak düz-geniş (a, e) ya da dar-yuvarlak (u, ü) bir ünlü gelebilir; ''doktor'' kelimesinde ise yuvarlak ''o'' ünlüsünden sonra yine geniş-yuvarlak ''o'' geldiği için kural bozulmuştur. Diğer kelimelerin tamamı küçük ünlü uyumuna uygundur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d46bd22e-5c11-486b-9f0c-5768bd9d69d4', 'doktor', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d46bd22e-5c11-486b-9f0c-5768bd9d69d4', 'kuzu', false, 1);
