insert into topic_contents (topic_id, summary, content_md, example_question) values ('9683464a-e0ce-493b-ae60-58c924e2ae5c', 'Bu konu; ''de/da'' bağlacı ile hâl eki, ''ki'' bağlacı ile ''-ki'' eki, ''mi'' soru eki ve büyük harf kullanımı gibi en sık karıştırılan yazım kurallarını örneklerle ele alır.', '## ''de/da'' Bağlacı ve Hâl Eki
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('d124c62a-8526-46e0-8e1e-e55f258ddd04', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ''de'' bağlaç olarak kullanılmış, bu nedenle ayrı yazılmıştır?', 'Bağlaç olan ''de/da'' ile hâl eki olan ''-de/-da''yı ayırt eder.', 'İkinci cümledeki ''da'', ''O bizimle gelmek istedi.'' cümlesinden çıkarıldığında anlam bütünlüğü bozulmadığı için bağlaçtır ve ayrı yazılır. Diğer cümlelerdeki ''-de'' ekleri isme bulunma hâli katan bir ek olduğu için bitişik yazılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d124c62a-8526-46e0-8e1e-e55f258ddd04', 'Sende kalan kitabımı getirir misin?', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d124c62a-8526-46e0-8e1e-e55f258ddd04', 'O da bizimle gelmek istedi.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d124c62a-8526-46e0-8e1e-e55f258ddd04', 'Evde kimse yoktu.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d124c62a-8526-46e0-8e1e-e55f258ddd04', 'Bahçede oynayan çocukları gördüm.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('228ea299-39ec-435d-bbd2-e04e0d1ecca1', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ''ki'' bağlaç olarak kullanılmış ve bu nedenle ayrı yazılmıştır?', 'Bağlaç ''ki'' ile sıfat yapan ''-ki'' ekini ayırt eder.', 'İkinci cümlede ''ki'', iki cümleyi birbirine bağlayan bir bağlaçtır ve ayrı yazılır. Diğer cümlelerde ''-ki'', isme sıfat ya da ilgi zamiri işlevi kazandıran bir ek olduğu için bitişik yazılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('228ea299-39ec-435d-bbd2-e04e0d1ecca1', 'Sokaktaki çocuklar top oynuyordu.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('228ea299-39ec-435d-bbd2-e04e0d1ecca1', 'Biliyordum ki bu iş kolay olmayacaktı.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('228ea299-39ec-435d-bbd2-e04e0d1ecca1', 'Benimki masanın üzerinde duruyor.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('228ea299-39ec-435d-bbd2-e04e0d1ecca1', 'Yarınki toplantıya katılamayacağım.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('da804d7f-9d9d-4054-976e-4d6c8b2b922c', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir yazım yanlışı vardır?', '''-ki'' ekinin bitişik yazılması gereken durumları fark eder.', '''Yarın'' kelimesine gelen sıfat yapan ''-ki'' eki bitişik yazılmalıdır; doğru yazım ''yarınki'' biçimindedir. Diğer cümlelerdeki yazımlar kurallara uygundur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('da804d7f-9d9d-4054-976e-4d6c8b2b922c', 'Yarın ki sınava çalışmalıyım.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('da804d7f-9d9d-4054-976e-4d6c8b2b922c', 'Sokaktaki köpek durmadan havlıyordu.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('da804d7f-9d9d-4054-976e-4d6c8b2b922c', 'O da toplantıya katılacağını söyledi.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('da804d7f-9d9d-4054-976e-4d6c8b2b922c', 'Kitaptaki resimleri çok beğendim.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('86d641d8-57e1-491f-af96-71f847be9af7', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde büyük harf kullanımıyla ilgili bir yanlışlık vardır?', 'Mevsim adlarının büyük harfle yazılmadığı kuralını uygular.', 'Mevsim adları hiçbir zaman büyük harfle başlamaz; bu nedenle ''ilkbahar'' kelimesi küçük harfle yazılmalıdır. Diğer cümlelerdeki büyük harf kullanımları (unvan, özel gün adı, dil adı) doğrudur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('86d641d8-57e1-491f-af96-71f847be9af7', 'Bu yıl İlkbahar çok erken geldi.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('86d641d8-57e1-491f-af96-71f847be9af7', 'Ahmet Bey toplantıya geç kaldı.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('86d641d8-57e1-491f-af96-71f847be9af7', '29 Ekim Cumhuriyet Bayramı''nı coşkuyla kutladık.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('86d641d8-57e1-491f-af96-71f847be9af7', 'Türkçe dersinde güzel bir şiir okuduk.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e4f17e50-babe-4eb4-99ca-71f63d1e37ed', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'zor'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir yazım yanlışı yoktur?', 'Birden fazla yazım kuralını bir arada değerlendirerek doğru cümleyi belirler.', 'İkinci cümlede bağlaç olan ''de'' doğru biçimde ayrı, soru eki ''mi'' de kurala uygun olarak ayrı yazılmıştır. Diğer cümlelerde sırasıyla ''kitapta'' yerine ''kitapda'', ''yarınki'' yerine ''yarın ki'' ve ''onunki'' yerine ''onun ki'' kullanılarak yazım yanlışı yapılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4f17e50-babe-4eb4-99ca-71f63d1e37ed', 'Kitapda ne yazdığını çok merak ediyorum.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4f17e50-babe-4eb4-99ca-71f63d1e37ed', 'Sen de mi bu işe karıştın?', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4f17e50-babe-4eb4-99ca-71f63d1e37ed', 'Yarın ki toplantıyı sakın unutma.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4f17e50-babe-4eb4-99ca-71f63d1e37ed', 'Herkes onun ki kadar başarılı olamadı.', false, 3);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'Virgül, iki nokta, noktalı virgül, kesme işareti, üç nokta ve ünlem işaretinin doğru kullanım kurallarını örneklerle açıklayan bu konu, noktalama hatalarını ayırt etmeyi hedefler.', '## Virgül (,)
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('c909077e-57a7-4ad8-aeb0-3d91835038e9', '4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde kesme işareti ('') doğru kullanılmıştır?', 'Kesme işaretinin özel isimlere gelen eklerde kullanıldığını kavrar.', '''Ahmet'' bir özel isim olduğu için aldığı ''-in'' eki kesme işaretiyle ayrılmıştır. Diğer seçeneklerdeki ''kalem, öğretmen, kitap'' cins isim olduğundan aldıkları ekler kesme işaretiyle ayrılmaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c909077e-57a7-4ad8-aeb0-3d91835038e9', 'Ahmet''in kitabını dün akşam okudum.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c909077e-57a7-4ad8-aeb0-3d91835038e9', 'Kalem''imi masanın üstünde unuttum.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c909077e-57a7-4ad8-aeb0-3d91835038e9', 'Öğretmen''e ödevimi teslim ettim.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c909077e-57a7-4ad8-aeb0-3d91835038e9', 'Kitab''ı çantama koydum.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('6997387f-b519-45e4-a884-9af9043a0134', '4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde virgül (,) doğru bir yerde kullanılmıştır?', 'Sıralama bildiren cümlelerde virgülün doğru kullanımını uygular.', 'Eş görevli kelimeler olan ''elma, armut, muz'' birbirinden virgülle ayrılmış, son öğeden önce ''ve'' bağlacı kullanıldığı için virgüle gerek duyulmamıştır. Diğer seçeneklerde virgüller anlamsız ya da gereksiz yerlere konmuştur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6997387f-b519-45e4-a884-9af9043a0134', 'Çarşıdan elma, armut, muz ve şeftali aldı.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6997387f-b519-45e4-a884-9af9043a0134', 'Çarşıdan, elma armut muz ve şeftali aldı.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6997387f-b519-45e4-a884-9af9043a0134', 'Çarşıdan elma armut, muz ve, şeftali aldı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6997387f-b519-45e4-a884-9af9043a0134', 'Çarşıdan elma armut muz, ve şeftali, aldı.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a3d2d354-0cda-4ef3-a8ac-886ccd4cbdfb', '4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde iki nokta (:) doğru kullanılmıştır?', 'İki noktanın örnek/liste verme işlevini kavrar.', 'Birinci cümlede iki nokta, kendisinden sonra bir liste (örnek) sıralanacağını haber verdiği için doğru kullanılmıştır. Diğer cümlelerde iki noktayı gerektiren bir açıklama ya da örnekleme durumu yoktur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a3d2d354-0cda-4ef3-a8ac-886ccd4cbdfb', 'Kırtasiyeden şunları aldım: kalem, silgi, defter.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a3d2d354-0cda-4ef3-a8ac-886ccd4cbdfb', 'Yarın: erken kalkıp işe gideceğim.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a3d2d354-0cda-4ef3-a8ac-886ccd4cbdfb', 'Bahçede: çiçekler yeni açmıştı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a3d2d354-0cda-4ef3-a8ac-886ccd4cbdfb', 'O gün: eve oldukça geç geldi.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('60118eaf-930e-41e5-851a-692adc7af501', '4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde noktalı virgül (;) doğru kullanılmıştır?', 'Noktalı virgülün virgüllerle ayrılmış öğe gruplarını ayırma işlevini uygular.', 'Birinci cümlede virgüllerle ayrılmış iki farklı kişi grubu (''Ali, Veli, Ayşe'' ve ''Mehmet, Fatma'') noktalı virgülle birbirinden ayrılmıştır. Diğer cümlelerde noktalı virgül gereksiz yere, herhangi bir öğe grubunu ayırmadan kullanılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60118eaf-930e-41e5-851a-692adc7af501', 'Sınıfta Ali, Veli, Ayşe; bahçede ise Mehmet, Fatma vardı.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60118eaf-930e-41e5-851a-692adc7af501', 'Bu kitabı; okuyup çok beğendim.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('60118eaf-930e-41e5-851a-692adc7af501', 'Yarın; erkenden okula gideceğim.', false, 2);
