insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('4b274b1d-ab39-4e7c-a6e1-e976a877170f', '4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'zor'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde noktalama işaretlerinin tamamı doğru kullanılmıştır?', 'Birden fazla noktalama kuralını bir arada değerlendirerek doğru cümleyi seçer.', 'İkinci cümlede iki nokta, kendisinden sonra gelen alıntı sözden önce doğru biçimde kullanılmış, tırnak içindeki alıntı da doğru noktalanmıştır. Diğer cümlelerde noktalı virgül gereksiz yere kullanılmış ya da ''masadaki'' kelimesine yanlışlıkla kesme işareti eklenmiştir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4b274b1d-ab39-4e7c-a6e1-e976a877170f', 'Ahmet''e, İstanbul''dan gelen; mektubu hemen verdim.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4b274b1d-ab39-4e7c-a6e1-e976a877170f', 'Öğretmenimiz: ''Yarın sınav var.'' dedi.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4b274b1d-ab39-4e7c-a6e1-e976a877170f', 'Masada''ki kitapları, düzenle dedi.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4b274b1d-ab39-4e7c-a6e1-e976a877170f', 'Çarşıya gidip; elma, armut aldım.', false, 3);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('d36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'Gerçek, mecaz, yan ve terim anlam ile eş anlam, zıt anlam, sesteşlik ve deyimlerin cümle içindeki kullanımını örneklerle işleyen sözcükte anlam konusu.', '## Gerçek (Temel) Anlam ve Mecaz Anlam
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2e371e08-b413-476e-8711-7397a6c7bd1e', 'd36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ''ağır'' sözcüğü mecaz anlamda kullanılmıştır?', 'Gerçek anlam ile mecaz anlamı ayırt eder.', 'İkinci cümlede ''ağır'' sözcüğü fiziksel bir ağırlığı değil, ''zor, çetin'' anlamını karşıladığı için mecaz anlamda kullanılmıştır. Diğer cümlelerde ''ağır'' sözcüğü nesnenin gerçek fiziksel ağırlığını belirtir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2e371e08-b413-476e-8711-7397a6c7bd1e', 'Bu çanta gerçekten çok ağırdı.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2e371e08-b413-476e-8711-7397a6c7bd1e', 'Sınav soruları oldukça ağırdı.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2e371e08-b413-476e-8711-7397a6c7bd1e', 'Valizi taşırken sırtım ağrıdı, çünkü çok ağırdı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2e371e08-b413-476e-8711-7397a6c7bd1e', 'Demir, ağır bir madendir.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('ce0cb19e-e44a-4e44-8dfc-2cca3e109540', 'd36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'kolay'::difficulty_level, 'Aşağıdaki kelime çiftlerinden hangisi eş anlamlıdır (anlamdaştır)?', 'Eş anlamlı (anlamdaş) kelimeleri tanır.', '''Kara'' ve ''siyah'' kelimeleri aynı rengi karşıladığı için eş anlamlıdır. Diğer seçeneklerdeki kelime çiftleri ise birbirinin zıt anlamlısıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ce0cb19e-e44a-4e44-8dfc-2cca3e109540', 'kara - siyah', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ce0cb19e-e44a-4e44-8dfc-2cca3e109540', 'büyük - küçük', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ce0cb19e-e44a-4e44-8dfc-2cca3e109540', 'sıcak - soğuk', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ce0cb19e-e44a-4e44-8dfc-2cca3e109540', 'ışık - karanlık', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('d4c27702-9c53-45a8-bb8e-04a927c936c9', 'd36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'orta'::difficulty_level, '''Eli kulağında'' deyimi aşağıdaki cümlelerin hangisinde doğru kullanılmıştır?', 'Deyimlerin cümle içindeki uygun kullanımını değerlendirir.', '''Eli kulağında'' deyimi bir işin bitmesine çok az kaldığını anlatır; birinci cümlede projenin yakında tamamlanacağı belirtildiği için deyim doğru bağlamda kullanılmıştır. Diğer cümlelerde deyimin anlamıyla cümlenin geri kalanı çelişmektedir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d4c27702-9c53-45a8-bb8e-04a927c936c9', 'Proje eli kulağında, birkaç güne kadar tamamlanmış olacak.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d4c27702-9c53-45a8-bb8e-04a927c936c9', 'Bu iş eli kulağında, çünkü daha yeni başladık.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d4c27702-9c53-45a8-bb8e-04a927c936c9', 'O her zaman eli kulağında biriydi.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('d4c27702-9c53-45a8-bb8e-04a927c936c9', 'Param eli kulağında bittiği için borç almak zorunda kaldım.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('9b1ebe49-51f6-44fb-820a-759c2adf1930', 'd36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ''yüz'' sözcüğü diğerlerinden farklı bir anlamda (sesteş olarak) kullanılmıştır?', 'Sesteş (eş sesli) kelimeleri cümle bağlamında ayırt eder.', 'İkinci cümlede ''yüzdü'', ''yüzmek'' eyleminden gelir ve suda hareket etmeyi ifade eder; diğer cümlelerdeki ''yüz'' ise ''çehre, surat'' anlamındaki isimdir. Yazılışları aynı fakat anlamları farklı olduğu için bu kelimeler sesteştir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9b1ebe49-51f6-44fb-820a-759c2adf1930', 'Yüzünde güzel bir gülümseme vardı.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9b1ebe49-51f6-44fb-820a-759c2adf1930', 'Denizde saatlerce yüzdü.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9b1ebe49-51f6-44fb-820a-759c2adf1930', 'Yüzü hafif kızarmıştı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('9b1ebe49-51f6-44fb-820a-759c2adf1930', 'Onun yüzüne bakamadım.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('fcbc6933-9234-47cc-ab40-28e2282bef73', 'd36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'zor'::difficulty_level, '''Kök'' sözcüğü aşağıdaki cümlelerin hangisinde terim anlamda (dil bilgisi terimi olarak) kullanılmıştır?', 'Terim anlamı gerçek ve mecaz anlamdan ayırt eder.', 'İkinci cümlede ''kök'', bir kelimenin anlam taşıyan en küçük parçasını belirten dil bilgisi terimi olarak kullanılmıştır. Diğer cümlelerde ''kök'' sözcüğü sırasıyla gerçek anlamda (bitki kökü) ve mecaz anlamda (kaynak, köken) kullanılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fcbc6933-9234-47cc-ab40-28e2282bef73', 'Bahçedeki ağacın kökü çok derinlere inmişti.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fcbc6933-9234-47cc-ab40-28e2282bef73', 'Bu kelimenin kökü Arapçadır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fcbc6933-9234-47cc-ab40-28e2282bef73', 'Sorunun kökünü araştırmalıyız.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fcbc6933-9234-47cc-ab40-28e2282bef73', 'Bu ailenin kökleri çok eskiye dayanıyor.', false, 3);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('eb6df17f-05d4-49df-b626-ba5d585672a9', 'Anlatım bozukluğu türlerini (gereksiz sözcük, çelişki, mantık hatası, tamlama yanlışlığı), öznel-nesnel yargı ayrımını ve cümle tamamlamayı örneklerle açıklayan konu.', '## Anlatım Bozukluğu Türleri
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('1e151cae-318c-461a-81de-a332701f381d', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisi nesnel bir yargı bildirmektedir?', 'Öznel yargı ile nesnel yargıyı ayırt eder.', 'Birinci cümlede sayfa sayısı, kişiden kişiye değişmeyen, kanıtlanabilir bir bilgi olduğu için nesneldir. Diğer cümleler kişisel görüş ve beğeni içerdiğinden özneldir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1e151cae-318c-461a-81de-a332701f381d', 'Roman, 320 sayfadan oluşmaktadır.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1e151cae-318c-461a-81de-a332701f381d', 'Bence bu roman çok sıkıcıydı.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1e151cae-318c-461a-81de-a332701f381d', 'Yazarın en başarılı eseri budur.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1e151cae-318c-461a-81de-a332701f381d', 'Bu film gelmiş geçmiş en iyi yapımdı.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('ffdf984d-5a4f-4101-a7c6-1ba250f8fd0e', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir anlatım bozukluğu vardır?', 'Gereksiz sözcük kullanımından kaynaklanan anlatım bozukluğunu fark eder.', '''Sevindirmek'' ve ''mutlu etmek'' aynı anlama geldiği için bu iki ifadenin bir arada kullanılması gereksiz tekrara, dolayısıyla anlatım bozukluğuna yol açmıştır. Diğer cümlelerde böyle bir tekrar yoktur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ffdf984d-5a4f-4101-a7c6-1ba250f8fd0e', 'Bu haber beni hem çok sevindirdi hem de mutlu etti.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ffdf984d-5a4f-4101-a7c6-1ba250f8fd0e', 'Öğrenciler sınava iyi hazırlandı.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ffdf984d-5a4f-4101-a7c6-1ba250f8fd0e', 'Kitabı okuyup arkadaşına anlattı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ffdf984d-5a4f-4101-a7c6-1ba250f8fd0e', 'Yağmur yağınca sokaklar ıslandı.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('0f90b77f-83f7-4e94-9c08-0d403dfe186b', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir anlatım bozukluğu vardır?', 'Çelişkiden kaynaklanan anlatım bozukluğunu tespit eder.', '''Belki'' ihtimal, ''kesinlikle'' ise kesinlik bildirir; bu iki ifade anlamca birbiriyle çeliştiği için cümlede anlatım bozukluğu vardır. Diğer cümlelerde böyle bir çelişki bulunmamaktadır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0f90b77f-83f7-4e94-9c08-0d403dfe186b', 'Belki de bu sınavı kesinlikle kazanacak.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0f90b77f-83f7-4e94-9c08-0d403dfe186b', 'Öğretmen konuyu tekrar anlattı.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0f90b77f-83f7-4e94-9c08-0d403dfe186b', 'Sabah erkenden yola çıktık.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0f90b77f-83f7-4e94-9c08-0d403dfe186b', 'Kitapları düzenli bir şekilde raflara yerleştirdi.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b7738c1f-62c1-4ab2-8f3b-39a15cb0c318', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir anlatım bozukluğu vardır?', 'Neden-sonuç ilişkisindeki mantık hatasını fark eder.', 'Cümlede önce parası olmadığı için kitabı alamadığı söylenmiş, ardından yine de aldığı belirtilerek çelişkili bir mantık hatası oluşturulmuştur. Diğer cümlelerde neden ile sonuç arasında tutarlı bir ilişki vardır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b7738c1f-62c1-4ab2-8f3b-39a15cb0c318', 'Param olmadığı için kitabı alamadım ama yine de aldım.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b7738c1f-62c1-4ab2-8f3b-39a15cb0c318', 'Erken kalktığım için derse zamanında yetiştim.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b7738c1f-62c1-4ab2-8f3b-39a15cb0c318', 'Yorgun olduğu için erken yattı.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b7738c1f-62c1-4ab2-8f3b-39a15cb0c318', 'Kitabı bitirince bana geri verdi.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('638d438a-99e6-4fff-a344-0daff9a4bfb1', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'zor'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir anlatım bozukluğu vardır?', 'Tamlama yanlışlığından kaynaklanan anlatım bozukluğunu ileri düzeyde tespit eder.', '''Ali'' kelimesinden sonra tamlayan eki ''-nin'' eksik bırakıldığı için cümlede tamlama yanlışlığı vardır; doğrusu ''Ali''nin ve babasının arabası'' biçiminde olmalıdır. Diğer cümlelerde böyle bir ek eksikliği yoktur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('638d438a-99e6-4fff-a344-0daff9a4bfb1', 'Ali ve babasının arabası kaza yaptı.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('638d438a-99e6-4fff-a344-0daff9a4bfb1', 'Ali''nin ve babasının arabası kaza yaptı.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('638d438a-99e6-4fff-a344-0daff9a4bfb1', 'Öğrenciler sınıfa girdi ve yerlerine oturdu.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('638d438a-99e6-4fff-a344-0daff9a4bfb1', 'Yağmur dinince hep birlikte dışarı çıktık.', false, 3);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('f884a167-9e40-4c5c-bc29-810eb13f200e', 'Paragrafta ana düşünce ve yardımcı düşünceyi ayırt etme, paragraf tamamlama ve metinden çıkarılabilecek/çıkarılamayacak yargıları belirleme becerilerini işleyen konu.', '## Konu ve Ana Düşünce
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('62616390-4dc6-4f30-9bbc-8db33857f318', 'f884a167-9e40-4c5c-bc29-810eb13f200e', 'kolay'::difficulty_level, '''İnsanlar günlük hayatlarında birçok karar verir. Bu kararların bazıları küçük, bazıları ise hayatı derinden etkileyecek kadar büyüktür. Küçük kararlar genellikle anlık düşünülüp hızla alınırken büyük kararlar için uzun süre düşünülür, çevredeki insanların fikirleri alınır. Çünkü büyük kararların sonuçları, kişinin hayatını uzun yıllar etkileyebilir.'' Bu parçanın ana düşüncesi aşağıdakilerden hangisidir?', 'Paragrafın ana düşüncesini belirler.', 'Parça, büyük kararların uzun süre düşünülerek ve başkalarının görüşü alınarak verilmesi gerektiğini, çünkü sonuçlarının kalıcı olduğunu vurgulamaktadır. Diğer seçenekler ya parçanın yalnızca bir kısmını yansıtır ya da metinde yer almayan aşırı bir genelleme içerir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('62616390-4dc6-4f30-9bbc-8db33857f318', 'İnsanlar hayatları boyunca sürekli karar alma durumundadır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('62616390-4dc6-4f30-9bbc-8db33857f318', 'Büyük kararlar, sonuçlarının kalıcı etkisi nedeniyle daha dikkatli ve uzun düşünülerek alınmalıdır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('62616390-4dc6-4f30-9bbc-8db33857f318', 'Küçük kararlar hızlı alındığı için önemsizdir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('62616390-4dc6-4f30-9bbc-8db33857f318', 'Çevredeki insanların fikirleri her zaman doğru kararlar verdirir.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2b0d8812-b9a5-4275-ab68-6134f70bb77a', 'f884a167-9e40-4c5c-bc29-810eb13f200e', 'kolay'::difficulty_level, '''Kitap okumak, insanın hayal gücünü geliştirir, kelime dağarcığını zenginleştirir ve empati kurma becerisini artırır. Ayrıca düzenli kitap okuyan bireylerin analitik düşünme yetenekleri de gelişir. Bu nedenle ______'' Bu parçada boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?', 'Paragrafın anlam akışına uygun tamamlama cümlesini seçer.', 'Parçada kitap okumanın sağladığı faydalar sıralandığı için mantıksal sonuç, bu alışkanlığın erken yaşta kazandırılması gerektiğidir. Diğer seçenekler parçanın konusuyla ilgisizdir ya da metinde değinilmeyen konulara değinir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2b0d8812-b9a5-4275-ab68-6134f70bb77a', 'televizyon izlemek de kitap okumak kadar faydalıdır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2b0d8812-b9a5-4275-ab68-6134f70bb77a', 'çocuklara küçük yaştan itibaren kitap okuma alışkanlığı kazandırılmalıdır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2b0d8812-b9a5-4275-ab68-6134f70bb77a', 'kitap okumanın hiçbir zararı yoktur.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2b0d8812-b9a5-4275-ab68-6134f70bb77a', 'herkesin aynı türde kitap okuması gerekir.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('dd2e98ec-308f-494d-b871-90e53c6e6960', 'f884a167-9e40-4c5c-bc29-810eb13f200e', 'orta'::difficulty_level, '''Şehirlerin hızla büyümesiyle birlikte yeşil alanlar giderek azalmaktadır. Betonlaşan kentlerde hava kalitesi düşmekte, sıcaklık artışları daha belirgin hissedilmektedir. Bununla birlikte bazı belediyeler, çatı bahçeleri ve dikey ormanlar gibi projelerle bu soruna çözüm aramaktadır. Ancak bu çabalar, kaybedilen yeşil alanların yerini tam olarak dolduramamaktadır.'' Bu parçanın ana düşüncesi aşağıdakilerden hangisidir?', 'Paragrafta ana düşünce ile yardımcı düşünceleri ayırt eder.', 'Parça, kentleşmeyle azalan yeşil alanlar için belediyelerin çözüm aradığını ama bu çabaların yeterli olmadığını vurgulamaktadır. Diğer seçenekler metinle çelişir ya da metinde yapılmayan bir karşılaştırma veya aşırı genelleme içerir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dd2e98ec-308f-494d-b871-90e53c6e6960', 'Belediyeler çevre sorunlarına duyarsız kalmaktadır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dd2e98ec-308f-494d-b871-90e53c6e6960', 'Kentleşmeyle azalan yeşil alanların yerini, alınan önlemler yeterince dolduramamaktadır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dd2e98ec-308f-494d-b871-90e53c6e6960', 'Çatı bahçeleri, dikey ormanlardan daha etkilidir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dd2e98ec-308f-494d-b871-90e53c6e6960', 'Hava kalitesi yalnızca sıcaklıkla ilgilidir.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a2d683d2-988e-4e05-9cd3-73af84e457fb', 'f884a167-9e40-4c5c-bc29-810eb13f200e', 'orta'::difficulty_level, '''______ Bu tür kitaplar, karmaşık bilimsel kavramları sade bir dille anlatarak okurun ilgisini çeker. Yazar, günlük hayattan örnekler kullanarak konuyu somutlaştırır. Böylece bilim, sadece uzmanların değil herkesin anlayabileceği bir alan hâline gelir.'' Bu parçanın başına aşağıdaki cümlelerden hangisi getirilmelidir?', 'Paragrafın başına gelecek en uygun giriş cümlesini belirler.', 'Parçanın devamında ''bu tür kitaplar'' ifadesiyle atıf yapılan konu, ancak popüler bilim kitaplarını tanıtan birinci seçenekle uyumludur. Diğer seçenekler parçanın konusuyla ilgisizdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a2d683d2-988e-4e05-9cd3-73af84e457fb', 'Popüler bilim kitapları, bilimi geniş kitlelere ulaştırmayı amaçlayan eserlerdir.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a2d683d2-988e-4e05-9cd3-73af84e457fb', 'Bilim insanları genellikle yalnız çalışmayı tercih eder.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a2d683d2-988e-4e05-9cd3-73af84e457fb', 'Roman yazarları hayal gücünü kullanarak eser üretir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a2d683d2-988e-4e05-9cd3-73af84e457fb', 'Her kitap mutlaka bir amaç taşımalıdır.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b28563ff-defe-40ec-8709-e8c117c20279', 'f884a167-9e40-4c5c-bc29-810eb13f200e', 'zor'::difficulty_level, '''Bir sanat eserinin değeri, yalnızca teknik ustalıkla ölçülemez. Tuval üzerine ustaca işlenmiş bir tablo, izleyicide hiçbir duygu uyandırmıyorsa amacına ulaşamamış demektir. Oysa bazen çok basit çizgilerle oluşturulmuş bir eser, izleyicisini derinden etkileyebilir, onu düşünmeye sevk edebilir. Bu nedenle sanatı değerlendirirken teknik beceri kadar, eserin izleyicide bıraktığı etkiye de bakmak gerekir.'' Bu parçadan aşağıdaki yargılardan hangisine ulaşılamaz?', 'Paragraftan çıkarılabilecek ve çıkarılamayacak yargıları ayırt eder.', 'Parçada sanatçının ününden hiç söz edilmediği için dördüncü seçenekteki yargıya metinden ulaşılamaz. Diğer seçenekler parçada doğrudan ya da dolaylı olarak ifade edilmiştir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b28563ff-defe-40ec-8709-e8c117c20279', 'Teknik açıdan kusursuz bir eser, izleyicide duygu uyandırmayabilir.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b28563ff-defe-40ec-8709-e8c117c20279', 'Basit görünen eserler de izleyici üzerinde güçlü bir etki bırakabilir.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b28563ff-defe-40ec-8709-e8c117c20279', 'Bir sanat eserini değerlendirirken hem teknik beceri hem de duygusal etki göz önünde bulundurulmalıdır.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b28563ff-defe-40ec-8709-e8c117c20279', 'Sanat eserlerinin değeri, yalnızca sanatçının ününe göre belirlenir.', true, 3);
